/**
 * App.js — ATHENA XAI Stock Predictor
 * Orchestrates all components. Contains only Welcome screen & layout logic.
 * Every visual piece lives in its own component file.
 */

import React, { useState, useEffect } from 'react';
import './App.css';

import Header            from './components/Header';
import StockSelector     from './components/StockSelector';
import LoadingSpinner    from './components/LoadingSpinner';
import PredictionCard    from './components/PredictionCard';
import FeatureImportance from './components/FeatureImportance';
import AttentionHeatmap  from './components/AttentionHeatmap';
import ExplanationPanel  from './components/ExplanationPanel';

import { predictStock, getHealth, getSupportedStocks } from './services/api';

const DEFAULT_STOCKS = [
  { ticker:'AAPL',  name:'Apple Inc.' },
  { ticker:'MSFT',  name:'Microsoft Corporation' },
  { ticker:'GOOGL', name:'Alphabet Inc.' },
  { ticker:'TSLA',  name:'Tesla Inc.' },
  { ticker:'AMZN',  name:'Amazon.com Inc.' },
  { ticker:'META',  name:'Meta Platforms Inc.' },
  { ticker:'NVDA',  name:'NVIDIA Corporation' },
  { ticker:'JPM',   name:'JPMorgan Chase & Co.' },
];

export default function App() {
  const [selected,    setSelected]    = useState('AAPL');
  const [prediction,  setPrediction]  = useState(null);
  const [loading,     setLoading]     = useState(false);
  const [error,       setError]       = useState(null);
  const [stocks,      setStocks]      = useState(DEFAULT_STOCKS);
  const [modelLoaded, setModelLoaded] = useState(false);

  useEffect(() => {
    getHealth()
      .then(h => setModelLoaded(!!h?.model_loaded))
      .catch(() => setModelLoaded(false));
    getSupportedStocks()
      .then(r => { if (r?.stocks?.length) setStocks(r.stocks); })
      .catch(() => {});
  }, []);

  const handleSelect = (ticker) => {
    setSelected(ticker);
    setPrediction(null);
    setError(null);
  };

  const handlePredict = async () => {
    setLoading(true);
    setError(null);
    setPrediction(null);
    try {
      const result = await predictStock(selected);
      setPrediction(result);
    } catch (e) {
      setError(
        e?.response?.data?.detail ||
        'Prediction failed. Is the FastAPI backend running on port 8000?'
      );
    } finally {
      setLoading(false);
    }
  };

  const stockName = stocks.find(s => s.ticker === selected)?.name || selected;

  return (
    <div className="app-root">
      <Header modelLoaded={modelLoaded} />

      <main className="app-main">
        <StockSelector
          stocks={stocks}
          selected={selected}
          onSelect={handleSelect}
          onPredict={handlePredict}
          loading={loading}
        />

        {error && (
          <div className="error-bar">
            <span>⚠️</span><span>{error}</span>
          </div>
        )}

        <LoadingSpinner active={loading} />

        {!prediction && !loading && !error && <Welcome />}

        {prediction && !loading && (
          <>
            <PredictionCard  prediction={prediction} stockName={stockName} />
            <FeatureImportance
              topFeatures={prediction.top_features    || []}
              importantDays={prediction.important_days || []}
            />
            <AttentionHeatmap regime={prediction.regime} />
            <ExplanationPanel prediction={prediction} />
          </>
        )}
      </main>

      <footer className="app-footer">
        <span>ATHENA · Explainable AI Financial Platform · Final Year Project 2025–26</span>
        <span>LSTM + Multi-Head Attention + SHAP + KMeans Regime · PyTorch · FastAPI · React</span>
      </footer>
    </div>
  );
}

function Welcome() {
  const features = [
    { i:'🧠', n:'LSTM + Attention',   d:'60-day lookback with multi-head temporal focus' },
    { i:'🔍', n:'SHAP Analysis',      d:'Game-theory feature attribution — every prediction explained' },
    { i:'📡', n:'Regime Detection',   d:'KMeans clustering: Calm · Trending · Volatile' },
    { i:'⚡', n:'Direction Ensemble', d:'LSTM head + RSI + MACD + MA cross combined' },
  ];
  return (
    <div className="welcome">
      <div className="welcome-title">EXPLAINABLE AI</div>
      <div className="welcome-sub">Predict. Understand. Trust. — Every decision backed by transparent AI reasoning.</div>
      <div className="feat-grid">
        {features.map((f, i) => (
          <div key={i} className="feat-card">
            <div className="feat-ico">{f.i}</div>
            <div className="feat-name">{f.n}</div>
            <div className="feat-desc">{f.d}</div>
          </div>
        ))}
      </div>
    </div>
  );
}
